INSERT INTO materials (id, grade_id, topic_slug, type, library, slug, position, status, is_teaser, created_at, updated_at) VALUES ('d9e5a4c3-6f7b-4c8d-9e0f-3a4b5c6d7e81','9','geografie-fizica','foto','student','relieful-minor-galerie-foto',16,'published',1,1783800000000,1783800000000);
INSERT INTO material_translations (material_id, locale, title, description, body) VALUES ('d9e5a4c3-6f7b-4c8d-9e0f-3a4b5c6d7e81','ro','Relieful minor — galerie foto','Galerie foto pentru lectia Relieful minor: forme de relief create de agentii externi (fluvial, glaciar, desertic, litoral, petrografic, structural, biogen).','{"captions":["relief fluvial – eroziune laterală (1), în adâncime (2) și acumulare (3)","relief fluvial – transportul aluviunilor (suspensie, soluție, târâre, saltație)","relief fluvial – elementele unei văi (albie minoră, luncă, terase, talveg)","relief de pluviodenudare – formarea rigolelor prin șiroire pe versant","relief gravitațional – elementele unei alunecări de teren (râpă, corp, pat, frunte)","relief gravitațional – alunecare de teren peste o așezare (vedere aeriană)","relief gravitațional – tasare și sufoziune în loess (crovuri, hornuri, tuneluri)","relief glaciar – elementele componente ale unei văi glaciare (circ, bazinet, prag, morene)","relief glaciar – circ glaciar","relief glaciar – vale glaciară în formă de U","relief glaciar – custură (creastă ascuțită)","relief glaciar – fiord (vale glaciară invadată de mare)","relief deșertic – dune de nisip","relief deșertic – ciupercă eoliană (modelată prin coraziune)","relief deșertic – inselberg (Uluru, Australia)","relief deșertic – hamada/reg (deșert pietros)","relief litoral – țărm cu fiorduri (Norvegia)","relief litoral – țărm cu rias (Spania)","relief litoral – țărm dalmatic (Croația)","relief litoral – faleză înaltă modelată prin abraziune (Cliffs of Moher)","relief fluvio-maritim – deltă (Delta Padului, Italia)","relief carstic – schema formelor carstice (lapiezuri, doline, uvale, polii, peșteri)","relief carstic – peșteră cu stalactite (1), coloane (2) și stalagmite (3)","relief vulcanic – coloane de bazalt (Racoș)","relief pe conglomerate – Sfinxul (Bucegi)","relief pe argile – badlands / pământuri rele (Râpa Roșie)","relief pe roci magmatice – căpățână de zahăr (granit, climat cald și umed)","relief structural – canion pe structură tabulară (strate orizontale)","relief structural – cuestă cu frunte și spinare (structură monoclinală)","relief structural – cueste și văi pe structură monoclinală (schemă)","relief structural – horst și graben (structură faliată)","relief biogen – mușuroi de termite","relief biogen – atol de corali"]}');
